"""Fecho de cada lição, no padrão do Política Para Iniciantes: três pontos para guardar e uma pergunta para pensar (transferência).
F[slug] = dict(guardar=[3 frases], pensar='pergunta aplicada à vida do leitor')."""
F = {
'o-que-e-etica': dict(guardar=['Ética é a pergunta “como devo agir, e por quê?”, feita com seriedade e aberta a razões.', 'Descrever o que as pessoas acham (ética descritiva) não responde o que se deve achar (ética normativa).', 'Juízos morais pedem razões, e razões podem ser boas ou ruins; por isso a ética se estuda, e não só se sente.'], pensar='Pense na última vez em que você disse que algo era “errado”. Que razão você daria se alguém perguntasse por quê? Ela valeria para um caso parecido com outras pessoas?'),
'etica-moral-lei-e-religiao': dict(guardar=['Legal não quer dizer certo, e proibido não quer dizer errado: a lei é uma tentativa humana, que a ética pode criticar.', 'Costume e etiqueta descrevem o que se faz; a moral pergunta o que se deve fazer.', 'A religião oferece motivação, comunidade e exemplos; a razão de um mandamento pode ser examinada por qualquer um.'], pensar='Liste uma coisa legal que você considera errada e uma proibida que considera certa. O que você usou para julgar, se não foi a lei?'),
'eticas-religiosas': dict(guardar=['Cada tradição coloca algo no centro: a lei, o amor, a submissão, o dharma, a compaixão, a não violência, as relações.', 'Quase todas chegam a alguma forma da regra de ouro e a deveres com o vulnerável.', 'A filosofia lê um mandamento separando a autoridade da razão que ele carrega; a razão pode ser aceita por quem não aceita a autoridade.'], pensar='Escolha um mandamento da tradição que você conhece melhor. Qual é a razão por trás dele? Alguém sem religião poderia aceitar essa razão?'),
'fatos-e-valores': dict(guardar=['Do que é não se tira sozinho o que deve ser: todo argumento moral tem uma premissa de valor, explícita ou escondida.', 'Fatos se checam com evidência; valores se discutem com argumentos e testes de imparcialidade.', 'Muitos desacordos de valor são desacordos de fato disfarçados, e se resolvem com informação.'], pensar='Pegue uma opinião política sua e escreva-a como um argumento: qual é a premissa de fato, qual é a de valor? Qual das duas você defenderia com mais dificuldade?'),
'argumentos-morais': dict(guardar=['Um argumento moral tem premissas e conclusão, e se avalia como qualquer outro: validade, verdade das premissas, coerência.', 'A coerência é a ferramenta mais poderosa: um princípio aceito num caso vale nos casos iguais, ou precisa de uma diferença relevante.', 'Apelos à natureza, à tradição e à maioria são os erros mais comuns, e têm nome para serem reconhecidos.'], pensar='Encontre dois juízos seus que usam o mesmo princípio em casos parecidos com vereditos diferentes. Que diferença entre os casos justifica isso? Se não houver, qual juízo você revisa?'),
'historia-da-etica': dict(guardar=['As perguntas mudaram menos do que as respostas: como viver bem, o que devemos, quem conta.', 'A modernidade fundou a moral sem Deus como premissa; o século XX perguntou o que é um juízo moral; o XXI discute as fronteiras do círculo.', 'O que mais avançou com clareza foi o círculo de quem conta; as teorias normativas seguem em disputa.'], pensar='Se um filósofo de 2200 olhasse para nós como olhamos para os romanos, que prática nossa ele teria mais dificuldade de entender?'),
'mapa-das-teorias': dict(guardar=['As famílias se distinguem pelo que colocam no centro: resultado, dever ou caráter; nenhuma ignora o resto.', 'Ponto focal é o que decide quando os critérios colidem, não a única coisa que a teoria vê.', 'A caricatura das teorias é o erro mais comum nas discussões de ética.'], pensar='Diante de uma decisão difícil recente, qual pergunta você fez primeiro: o que vai acontecer, qual é o meu dever, ou que pessoa quero ser? Isso diz algo sobre o seu ponto focal.'),
'consequencialismo': dict(guardar=['A ação certa é a que produz o melhor resultado para todos os afetados, cada um contando por um.', 'A ideia atrai porque leva a sério o que acontece com quem é afetado; é também a fonte das objeções: pode exigir demais e sacrificar alguém pela soma.', 'A família tem decisões internas: ato ou regra, o que conta como bem, como juntar o bem de vários.'], pensar='Pense numa regra que você segue sempre, mesmo quando quebrá-la daria um resultado melhor. Por que a mantém? Um consequencialista de regras diria o mesmo?'),
'deontologia': dict(guardar=['Algumas coisas não se fazem a uma pessoa, mesmo com bons resultados: cada pessoa é um fim, não um meio.', 'Direitos vencem cálculos comuns; se vencem sempre (absolutismo) ou cedem diante da catástrofe (limiar) é a disputa interna.', 'A deontologia protege pessoas, não regras; por isso discute conflitos, exceções e limiares.'], pensar='Há algo que você não faria a alguém por nenhum resultado? Nomeie. Agora imagine o pior resultado possível de não fazer. Você ainda não faria?'),
'etica-do-carater': dict(guardar=['A pergunta “que pessoa devo ser?” vem antes de “o que devo fazer?”: o caráter prevê o que se faz quando ninguém olha.', 'A ética do cuidado começa nas relações de dependência, que são a condição humana, não a exceção.', 'A objeção comum às duas é que não dizem o que fazer no caso difícil; a resposta é a sabedoria prática.'], pensar='Pense em alguém que você admira moralmente. Que traços ele tem? Você consegue dizer o que ele faria num dilema seu, sem perguntar a ele?'),
'egoismo-relativismo-e-ceticismo': dict(guardar=['Egoísmo psicológico (como as pessoas são) não implica egoísmo ético (como devem ser), e a evidência contradiz o primeiro.', 'O relativismo cultural torna o reformador sempre errado e o progresso impossível; a tolerância precisa de uma base que ele não dá.', 'O cético normativo diz que nenhum juízo é mais justificado; na prática, até ele se indigna com injustiças.'], pensar='“Quem sou eu para julgar?” Pense numa prática de outra cultura que você considera errada. Você consegue dizer por quê sem usar “na minha cultura”?'),
'circulo-moral': dict(guardar=['Consideração direta é valer por si; indireta é valer por causa de outro. O carro vale pelo dono; o cachorro vale por si, porque sente.', 'Os critérios candidatos são senciência, razão, laços e espécie; cada um inclui e exclui grupos diferentes.', 'A pergunta que organiza o debate: que traço é relevante para alguém poder ser prejudicado?'], pensar='Faça uma lista rápida de quem conta para você: pessoas próximas, estranhos, animais, gerações futuras. Qual critério explica a lista inteira? Ele deixa alguém de fora por um traço irrelevante?'),
'expansao-do-circulo-moral': dict(guardar=['Escravizados, mulheres, estrangeiros e outros grupos já ficaram fora de quem conta; o círculo cresceu por conflito e argumento, não por tempo.', 'O motor da expansão é mostrar que o traço usado para excluir é irrelevante para o que está em jogo.', 'Cada expansão corrigiu uma incoerência entre o que a sociedade dizia valer e o que praticava.'], pensar='Que exclusão de hoje seus netos vão achar difícil de entender? Que princípio que você já aceita, aplicado com coerência, a alcançaria?'),
'imparcialidade': dict(guardar=['Regra de ouro, véu da ignorância e universalidade são três testes para saber se você defende um princípio ou só o seu lado.', 'Os testes empurram o círculo para fora: o que torna um lugar ruim é o sofrimento, não a espécie.', 'Eles eliminam princípios parciais, mas não escolhem entre princípios imparciais rivais.'], pensar='Pegue uma posição sua sobre um grupo a que você não pertence. Sob o véu da ignorância, sem saber se nasceria nesse grupo, você a manteria?'),
'igualdade-humana': dict(guardar=['Igualdade de fato é falsa; igualdade de consideração é o que se defende: interesses iguais contam igual, por mais diferentes que sejam as capacidades.', 'Consideração igual exige tratamento diferente quando as necessidades diferem.', 'Talentos são sorte na loteria natural e não geram direito a mais consideração (Rawls).'], pensar='Pense em alguém com uma capacidade muito menor que a sua em algo que você faz bem. A dor dessa pessoa vale menos que a sua? Se não, o que a igualdade está afirmando?'),
'parcialidade-e-deveres-especiais': dict(guardar=['Deveres especiais nascem de relações, promessas e papéis, e são reais.', 'Uma ética imparcial justifica a parcialidade: um mundo em que cada um cuida dos seus é melhor para todos.', 'A parcialidade vira exclusão quando serve para negar aos de fora a consideração mínima que lhes é devida.'], pensar='Quanto a mais você deve aos seus do que a um estranho? Tente dar um número ou uma regra. Onde a sua regra deixa de ser cuidado e vira indiferença pelos outros?'),
'dilemas-do-cotidiano': dict(guardar=['A vida moral acontece em decisões pequenas e repetidas: mentiras, promessas, compras, trabalho.', 'Cada compra sustenta uma cadeia de afetados que você não vê; escolher é decidir quem paga.', 'O roteiro começa por quem é afetado e como; a teoria vem depois.'], pensar='Escolha uma decisão rotineira sua (uma compra, uma mentira branca, uma promessa) e aplique o roteiro da lição. O resultado mudou algo?'),
'como-discutir-etica': dict(guardar=['Separe primeiro o desacordo de fato do desacordo de valor; muitas brigas misturam os dois.', 'Explique a posição do outro de um jeito que ele aceitaria; se não reconhece, você discute com um boneco de palha.', 'Diga o que faria você mudar de ideia antes de pedir isso ao outro.'], pensar='Na próxima discussão, tente resumir a posição do outro antes de responder e pergunte se acertou. O que muda na conversa?'),
'perguntas-frequentes': dict(guardar=['“É natural”, “sempre foi assim” e “todo mundo faz” descrevem; não justificam.', '“Quem sou eu para julgar?” abandona a vítima: julgar com razões não é se achar superior.', 'Respostas curtas são resumos; a lição ligada é para quando a conversa aperta.'], pensar='Qual dessas sete perguntas você mesmo já fez? Depois da resposta da lição, ela ainda parece uma objeção à ética?'),
'utilitarismo-classico': dict(guardar=['Bentham: a maior felicidade do maior número, com cada um contando por um; Mill: prazeres têm qualidade, não só quantidade.', 'Julgar o ato ou julgar a regra é a divisão interna mais importante.', 'A teoria continua viva porque o que ela vê, quem fica melhor e quem fica pior, nenhuma outra pode ignorar.'], pensar='Imagine uma decisão pública da sua cidade (um parque, um abrigo, uma estrada). Faça a conta de Bentham e depois a correção de Mill. O resultado mudou?'),
'teorias-do-bem-estar': dict(guardar=['Três respostas sobre o que é bom para quem vive: prazer, desejos satisfeitos, uma lista de bens.', 'A máquina de experiências e a vida enganada são os testes do hedonismo; a lista objetiva paga com a pergunta “quem decide a lista?”.', 'A escolha da teoria do bem-estar muda as conclusões práticas de qualquer consequencialismo.'], pensar='Você entraria na máquina de experiências por uma vida inteira? Se não, o que você quer além de sentir que as coisas vão bem?'),
'somar-priorizar-ou-garantir': dict(guardar=['Dizer que o resultado importa não diz como juntar o bem de várias pessoas: somar, priorizar os piores, proteger o pior, igualar ou garantir um piso.', 'O prioritarismo atrai porque dá peso extra a quem está pior sem o problema do nivelamento por baixo.', 'Na prática, a diferença aparece quando ajudar os piores custa mais do que ajudar os demais.'], pensar='Com um orçamento fixo, você daria dez anos de vida a uma pessoa saudável ou dois anos a alguém muito doente? Qual das cinco regras sua resposta segue?'),
'o-peso-do-sofrimento': dict(guardar=['Quatro enfoques: simetria, prioridade ao sofrimento, utilitarismo negativo, ética focada no sofrimento.', 'A intuição de que há sofrimentos que nenhum prazer compensa é o ponto de partida da assimetria.', 'As versões defendidas hoje dão ao sofrimento prioridade, não exclusividade.'], pensar='Você aceitaria um dia de agonia extrema em troca de uma semana de alegria intensa? E um mês? Sua resposta diz quanto de assimetria você aceita.'),
'objecoes-ao-consequencialismo': dict(guardar=['Sete objeções clássicas: sacrifícios, exigência, cálculo, separação das pessoas, monstro e conclusão repugnante, integridade, direitos.', 'Cada objeção tem resposta, e as respostas geraram as versões de regras, satisfatória e com restrições.', 'As objeções mostram o custo de cada versão, não a morte da família.'], pensar='Qual das sete objeções pesa mais para você? Qual resposta consequencialista a ela você acha menos convincente, e por quê?'),
'fazer-e-deixar-acontecer': dict(guardar=['Smith e Jones: quando intenção e resultado são iguais, a diferença entre matar e deixar morrer não muda a avaliação.', 'A distinção importa onde há diferença de intenção, de meio ou de custo; não vale como desculpa geral.', 'O viés de omissão faz a omissão parecer neutra; ela também é escolha.'], pensar='Liste três danos que você “deixa acontecer” sem causar (uma doação não feita, um aviso não dado). Em qual deles a distinção fazer/permitir de fato o desculpa?'),
'um-cenario-melhor-ou-o-melhor': dict(guardar=['“Melhorou” compara com o passado; “bom” compara com o possível; a comparação que decide é com as alternativas reais.', 'Contentar-se com qualquer melhora e exigir o ideal são erros simétricos.', 'Satisfazer é racional sob limites; vira desculpa quando o melhor estava ao alcance.'], pensar='Pense numa mudança que você fez e chamou de “melhora”. Comparada com o que você podia ter feito, ela foi o melhor cenário disponível?'),
'kant-e-o-imperativo-categorico': dict(guardar=['Imperativos hipotéticos dependem de um fim; o categórico obriga sem “se”.', 'Primeira fórmula: aja só por uma máxima que possa ser lei universal sem contradição; segunda: trate a humanidade sempre como fim, nunca apenas como meio.', 'A força de Kant é a dignidade igual; o problema é a rigidez (o assassino à porta).'], pensar='Escolha uma pequena desonestidade que você considera aceitável. Universalize-a: se todos fizessem, a prática de que ela depende sobreviveria?'),
'direitos-e-limiares': dict(guardar=['Direitos são trunfos: vencem cálculos de utilidade comuns.', 'Absolutismo diz que nunca cedem; a deontologia de limiar diz que cedem diante da catástrofe, e precisa dizer onde fica o limiar.', 'Direitos morais são o que a lei deveria reconhecer, e servem para criticar a lei.'], pensar='Um direito que você considera absoluto: existe algum número de vidas que o faria ceder? Se sim, você é um deontologista de limiar; se não, aceita a catástrofe. Qual custo prefere?'),
'intencao-e-previsao': dict(guardar=['Duplo efeito: um dano previsto como efeito colateral de um bem pode ser permitido; um dano pretendido como meio, não.', 'A crítica: a vítima não nota a diferença; a defesa: a intenção prevê o que o agente faria se o meio falhasse.', 'Deveres prima facie (Ross) são reais e podem ser vencidos por outro dever no caso; o juízo decide.'], pensar='Pense num ato seu que causou um dano que você não queria, mas previu. Você o teria feito se o dano fosse o meio, e não o efeito colateral? A diferença importa para você?'),
'etica-e-religiao': dict(guardar=['Eutífron: algo é bom porque Deus manda (arbitrariedade) ou Deus manda porque é bom (independência)?', 'A resposta modificada coloca a bondade na natureza de Deus; resta saber se isso resolve ou desloca a pergunta.', 'Religião e ética se oferecem coisas: motivação e comunidade de um lado; critérios de interpretação do outro.'], pensar='Se você descobrisse que Deus não existe, ou que existe, o que mudaria no que você considera certo? A resposta diz onde a sua moral está ancorada.'),
'aristoteles-e-as-virtudes': dict(guardar=['Eudaimonia é florescer, não sentir-se bem; a virtude é o hábito que torna isso possível.', 'O meio-termo é a medida certa para o caso, não a moderação em tudo; algumas coisas não têm meio.', 'A sabedoria prática é a virtude que aplica as outras; sem ela, a teoria não decide.'], pensar='Escolha uma virtude que você quer ter mais. Que prática diária, pequena, a formaria como hábito? Aristóteles diria que é por aí.'),
'etica-do-cuidado': dict(guardar=['Gilligan contra Kohlberg: a voz do cuidado não era imaturidade, era outro raciocínio moral.', 'Cuidar envolve atenção, resposta e responsabilidade; a dependência é a condição humana.', 'A objeção: o cuidado é parcial e começa perto; precisa da imparcialidade para alcançar quem não vemos.'], pensar='Quem cuida de você hoje, e de quem você cuida? Essas relações aparecem em alguma das teorias que você leu antes? O que elas revelam que o contrato não vê?'),
'etica-feminista': dict(guardar=['Três etapas: incluir as mulheres nas teorias, criticar as teorias, levar a justiça às estruturas e à família.', 'Autonomia relacional, injustiça epistêmica e interseccionalidade são conceitos que a ética feminista deu a todas as teorias.', 'O método é perguntar quem ficou fora da teoria e o que muda quando entra; ele serve para outros excluídos.'], pensar='Pegue uma teoria da ética que você gosta e pergunte: para quem ela foi pensada? Que experiência humana ela deixa de ver por isso?'),
'educacao-moral': dict(guardar=['O caráter se forma pelo hábito e pelo exemplo; as razões vêm depois, para quem já pratica.', 'Educação forma quem pode discordar do educador; doutrinação, quem não pode.', 'Adultos também se educam moralmente: pelo ambiente, pelos pares e pelo que praticam.'], pensar='O que você aprendeu de moral com quem o criou veio mais do que diziam ou do que faziam? O que alguém aprende hoje olhando o que você faz?'),
'sentido-da-vida': dict(guardar=['Sentido não é felicidade nem moralidade: é envolver-se com algo que vale a pena (Wolf).', 'O absurdo (Nagel) não cancela o ponto de vista de dentro; a vida não precisa de justificação cósmica.', 'A ética não pode ocupar a vida inteira; e contribuir para o bem de outros é uma das fontes mais seguras de sentido.'], pensar='O que, na sua vida, você faria mesmo que ninguém soubesse e que não lhe desse prazer imediato? Isso é um bom indicador do que dá sentido a ela.'),
'contratualismo': dict(guardar=['Hobbes: paz entre interessados; Rawls: justiça escolhida sob o véu; Scanlon: o que ninguém poderia razoavelmente rejeitar.', 'O problema clássico é quem fica fora do contrato: animais, bebês, gerações futuras.', 'Esconder a espécie sob o véu muda as regras sobre os animais; a exclusão original foi decisão, não necessidade.'], pensar='Sob o véu da ignorância, sem saber se nasceria humano ou um dos animais que a sociedade cria, que regra sobre a criação de animais você aceitaria?'),
'psicologia-moral': dict(guardar=['O elefante vai primeiro, e o condutor racionaliza; a razão guia a intuição só com esforço, tempo e conversa.', 'Explicar a origem de um juízo não diz se ele é verdadeiro; dá um alerta sobre quais intuições merecem suspeita.', 'Os dois sistemas de Greene explicam a diferença entre o desvio e a passarela; não a justificam.'], pensar='Lembre de um juízo moral forte seu que você não consegue justificar bem quando pressionado. Ele vem do elefante? Isso o torna suspeito, ou só menos articulado?'),
'emocoes-morais': dict(guardar=['Emoções são como percebemos o que importa; sem elas, o juízo fica inerte.', 'Culpa é sobre o que fiz e leva a reparar; vergonha é sobre o que sou e leva a esconder.', 'A empatia vê um rosto e é cega ao número; a compaixão guiada pela razão alcança quem não tem rosto.'], pensar='Que emoção moral você sente com mais frequência: indignação, culpa, nojo, compaixão? Em que caso recente ela acertou, e em qual o enganou?'),
'situacionismo-e-experimentos': dict(guardar=['Milgram, Zimbardo e Arendt mostram que a situação pesa mais sobre a conduta do que supomos.', 'A objeção situacionista não prova que o caráter não existe: um terço resistiu em Milgram, e replicações reduziram alguns efeitos.', 'A virtude inclui conhecer as situações perigosas e evitá-las ou preparar-se para elas.'], pensar='Em que situação você já fez algo que não faria “normalmente”? O que naquela situação o empurrou? O que faria diferente hoje, sabendo disso?'),
'vieses-morais': dict(guardar=['Vítima identificável, insensibilidade à escala, proximidade, omissão e status quo são atalhos de todo cérebro.', 'A dissonância se resolve muitas vezes mudando a crença em vez do ato.', 'A proteção é olhar os números antes de decidir e fixar regras com antecedência.'], pensar='Qual viés desta lição você reconhece numa decisão sua desta semana? Que regra fixada de antemão o teria evitado?'),
'fraqueza-de-vontade': dict(guardar=['Acrasia é agir contra o próprio juízo; existe, e não é hipocrisia.', 'Entre a crença e o ato competem hábito, custo, pressão social e vieses; argumentos mudam crenças, que são necessárias e não suficientes.', 'O que ajuda a vontade é mudar o ambiente, criar hábitos e assumir compromissos públicos.'], pensar='Nomeie uma coisa que você acredita que deveria fazer e não faz. O que compete com a crença: hábito, custo, pressão? Que mudança de ambiente tornaria o certo mais fácil?'),
'livre-arbitrio-e-responsabilidade': dict(guardar=['Compatibilismo: ser responsável é agir pelas próprias razões sem coerção, e isso é compatível com ter causas.', 'Os casos de Frankfurt mostram responsabilidade sem possibilidade de fazer diferente.', 'Sorte moral: julgamos por resultados e circunstâncias que ninguém controla; a maioria reduz o peso do resultado e mantém o da intenção.'], pensar='Pense em algo de que você se orgulha e em algo de que se envergonha. Quanto de cada um dependeu de sorte (nascimento, circunstância, acaso)? O que sobra de mérito e de culpa?'),
'tribalismo-moral': dict(guardar=['Tribalismo moral é descontar quem está fora do grupo por um traço irrelevante; persiste mesmo em quem busca imparcialidade.', 'Dezesseis eixos, o mesmo mecanismo; a nação é o tribalismo que ainda é respeitável.', 'O teste de troca pergunta se o veredito muda com o grupo e não com o ato.'], pensar='Em qual dos dezesseis eixos você se pega descontando o sofrimento de alguém? Aplique o teste de troca a um caso recente.'),
'pobreza-e-etica-global': dict(guardar=['Singer: se salvar com custo pequeno é devido no lago, é devido à distância; Pogge: os ricos sustentam regras que empobrecem, e devem reparar.', 'As objeções (distância, exigência, eficácia, instituições) têm respostas, e a mais forte é a da exigência.', 'Algumas intervenções têm efeito grande e medido; escolher onde doar importa centenas de vezes.'], pensar='Quanto você gastou este mês com coisas de que não precisava? Que fração disso, doada a uma organização eficaz, você estaria disposto a comprometer todo mês?'),
'economia-politica-e-etica': dict(guardar=['Toda teoria econômico-política carrega uma resposta ética: o que é justo, quem conta, o que vale mais.', 'Cada sistema tem um valor central e um ponto cego; nenhum conta os animais nem o futuro distante por padrão.', 'A ética cobra de todos: o que fazem com quem está pior, com quem não vota e com quem ainda não nasceu.'], pensar='Qual vertente econômica você prefere? Diga o valor ético que ela coloca no centro e o grupo que ela tende a esquecer. Você aceita esse ponto cego?'),
'exploracao': dict(guardar=['Explorar é tirar vantagem injusta, e pode acontecer numa troca que beneficia os dois lados.', 'O consentimento dado sem alternativa real vale pouco; aceitar é compatível com ser explorado.', 'O remédio raramente é proibir a troca; é dar a quem precisa alternativas e poder de dizer não.'], pensar='Pense numa troca de que você participa (como cliente, patrão ou trabalhador) em que um lado tem muito mais alternativas do que o outro. A divisão do ganho é justa?'),
'bioetica': dict(guardar=['A bioética nasceu de escândalos: Nuremberg, Tuskegee, Belmont; cada regra tem uma história.', 'Quatro princípios prima facie: autonomia, beneficência, não maleficência, justiça; quando colidem, pesa-se.', 'Consentimento informado é o centro, e tem limites: capacidade, informação, ausência de coerção.'], pensar='Se um parente seu, lúcido, recusasse um tratamento que o salvaria, você respeitaria? Que princípio pesaria mais para você, e por quê?'),
'deficiencia-e-etica': dict(guardar=['Modelo social: a deficiência vive no encontro entre o corpo e um ambiente que não o acomoda; a resposta é a rampa, não só a cura.', 'Kittay: a dependência é a condição humana; uma teoria da justiça que começa por independentes começa pela metade.', 'O debate com Singer expõe que o critério das capacidades, usado para incluir animais, pode graduar humanos; a resposta sencientista é que a dor conta igual para todos.'], pensar='Olhe o prédio, o site ou o serviço onde você trabalha ou estuda: que pessoa ele deixa de fora? O problema está na pessoa ou no desenho?'),
'etica-da-tecnologia': dict(guardar=['Algoritmos herdam vieses dos dados; “foi o sistema” não pode ser o fim da conversa.', 'O problema das muitas mãos pede responsabilidade desenhada antes do dano.', 'Desenho que maximiza atenção contornando a vontade do usuário trata-o como meio.'], pensar='Pegue um aplicativo que você usa todo dia. Que decisão de desenho dele serve a você, e qual serve a quem o fez? Ele passaria no teste de transparência?'),
'responsabilidade-coletiva': dict(guardar=['Culpa é individual e exige ato; responsabilidade pode ser coletiva, pelo que o grupo faz em nosso nome (Arendt, Jaspers).', 'Young: quem participa de uma estrutura injusta tem responsabilidade voltada para a frente, compartilhada e coletiva.', '“Minha parte não muda nada” tem três respostas: valor esperado, torturadores inofensivos, cumplicidade.'], pensar='De que estrutura injusta você participa todo dia (consumo, trabalho, voto)? Que ação coletiva, não só individual, está ao seu alcance para mudá-la?'),
'o-dilema-do-bonde': dict(guardar=['Desviar (sim) e empurrar (não) com o mesmo número de mortos: a diferença isola o que decide nossos juízos.', 'As explicações candidatas: usar alguém como meio, contato físico, intenção contra previsão; as variantes testam cada uma.', 'O bonde é instrumento de diagnóstico, não veredito; carros autônomos e triagem são bondes reais.'], pensar='Qual é a sua resposta ao desvio e à passarela? Diga a regra que explica as duas. Ela sobrevive ao caso do transplante?'),
'experimentos-mentais': dict(guardar=['Experimentos mentais isolam uma variável de propósito; testam a coerência de um princípio, não a frequência do caso.', 'Máquina, lago, violinista, anel, monstro, Omelas e último homem testam, cada um, um princípio diferente.', 'O mau experimento é o que esconde a variável, não o que simplifica.'], pensar='Qual destes experimentos mais abalou uma convicção sua? Que princípio ele testou, e o que você fez com o resultado?'),
'o-que-e-metaetica': dict(guardar=['A metaética pergunta o que fazemos ao julgar: descrever um fato, expressar uma atitude, dar uma ordem?', 'Três perguntas: semântica, metafísica e epistêmica; o mapa vai do realismo ao quietismo.', 'A metaética não diz o que fazer, mas muda como se discute e o que conta como erro moral.'], pensar='Quando você diz que algo é errado, o que acha que está fazendo: relatando um fato, expressando o que sente, pedindo que os outros parem? Sua resposta é a sua metaética provisória.'),
'realismo-moral': dict(guardar=['Realismo: há fatos morais independentes das opiniões; naturalistas os veem como fatos naturais, não naturalistas como fatos de outro tipo.', 'A favor: a fenomenologia do juízo, o desacordo que parece real, o progresso; contra: a estranheza e o desmascaramento.', 'O realista pode estar errado sobre quais são os fatos; é o que o torna humilde.'], pensar='“A escravidão era errada mesmo quando quase todos a aceitavam.” Você concorda? Verdadeira em relação a quê? Sua resposta o aproxima ou o afasta do realismo?'),
'antirrealismo-moral': dict(guardar=['Teoria do erro: os juízos pretendem descrever fatos que não existem; emotivismo e prescritivismo: eles expressam atitudes ou ordens; quase-realismo: explica a lógica moral sem fatos.', 'Frege-Geach é a objeção mais forte ao emotivismo simples.', 'Antirrealistas levam a moral a sério; o que discutem é o estatuto dos juízos.'], pensar='Se você se convencesse de que não há fatos morais, mudaria alguma coisa no que faz? Se não, o que isso diz sobre de onde vem a força dos seus juízos?'),
'relativismo-e-quietismo': dict(guardar=['Relativismo metaético: a verdade moral é relativa a um referencial, como a gramática a uma língua; custa a possibilidade de progresso.', 'Quietismo: a pergunta metafísica está mal posta; só argumentos morais defendem juízos morais.', 'O relativismo normativo (“tolere as outras culturas”) é uma tese universal e se contradiz.'], pensar='Você acha que a abolição da escravidão foi um acerto, e não só uma mudança? Se sim, que teoria metaética permite dizer isso?'),
'evolucao-e-moral': dict(guardar=['A evolução moldou intuições morais: cuidado com os filhos, lealdade ao grupo, repulsa.', 'Street: o realista precisa explicar como intuições selecionadas para sobreviver rastreariam verdades independentes.', 'Explicar não é justificar; intuições que sobrevivem à reflexão imparcial (o sofrimento é mau) são mais confiáveis do que as tribais.'], pensar='Qual das suas intuições morais parece mais claramente útil à sobrevivência do grupo? Ela resiste quando você a examina de um ponto de vista imparcial?'),
'epistemologia-moral': dict(guardar=['Diante do desacordo entre pares, reduza um pouco a confiança: um de vocês errou, e você não tem razão para supor que foi o outro.', 'Testemunho moral é suspeito porque agir bem exige entender a razão, não só saber a conclusão.', 'Conhecemos em ética por intuição, coerência e reflexão: o equilíbrio reflexivo.'], pensar='Quem é a pessoa mais informada e honesta que discorda de você em ética? Quanto essa discordância deveria pesar? Quanto pesa de fato?'),
'motivacao-moral': dict(guardar=['Internalismo: julgar traz alguma motivação; externalismo: juízo e motivação são separados; o amoralista é o caso de teste.', 'Smith: crenças morais, motivação pelo juízo e psicologia humeana não cabem juntas; cada metaética sacrifica uma.', 'Williams: razões ligam-se ao que a pessoa já quer; Korsgaard e McDowell respondem.'], pensar='Pense numa convicção moral sua que não move você a agir. Falta a crença, falta o desejo, ou falta a ponte? O que construiria a ponte?'),
'etica-da-crenca': dict(guardar=['Clifford: crer sem evidência é errado quando outros dependem da crença; o resultado feliz não absolve.', 'James: em questões vivas, forçadas e sem evidência disponível, é permitido crer; o limite é onde a evidência existe.', 'As virtudes epistêmicas (humildade, honestidade, curiosidade, coragem) são virtudes morais.'], pensar='Que crença sua afeta outras pessoas e foi formada sem checar? O armador de Clifford faria o mesmo? O que custaria checar?'),
'senciencia': dict(guardar=['Senciência é a capacidade de ter experiências com valor, como dor e prazer; é o que torna alguém capaz de ser prejudicado.', 'A ciência investiga por convergência de indicadores; para vertebrados e alguns invertebrados a evidência é forte.', 'Sob incerteza, dê peso proporcional à probabilidade e evite danos graves quando a chance é real.'], pensar='Que ser você trata hoje como se não sentisse (um peixe, um inseto, uma lagosta)? Que evidência você usou? Que probabilidade de senciência você daria, e o que ela implica?'),
'especismo': dict(guardar=['Igual consideração de interesses: interesses iguais contam igual; a espécie, por si, é um traço como a raça.', 'Casos marginais: qualquer capacidade usada para excluir animais também exclui alguns humanos; o critério real é sentir.', 'Regan: todo sujeito de uma vida tem direitos; Singer: interesses iguais, peso igual; os críticos buscam a diferença relevante.'], pensar='Escreva a diferença entre um humano e um porco que, para você, justifica contar a dor de um por menos. Ela vale para todos os humanos? Se não, o que resta?'),
'etica-animal-na-pratica': dict(guardar=['O sofrimento se concentra na criação industrial e na pesca, longe da vista.', 'Cada teoria chega a conclusões parecidas sobre a criação industrial, por caminhos diferentes.', 'O efeito maior vem de mudar o que se come, apoiar campanhas institucionais e doar a organizações eficazes.'], pensar='Das ações desta lição, qual você já faz, qual poderia começar esta semana e qual acha difícil? O que torna a difícil difícil: custo, hábito ou pressão?'),
'sofrimento-dos-animais-selvagens': dict(guardar=['A maioria dos animais que nascem morre cedo, de fome, doença ou predação; a natureza não é um documentário.', 'Se o sofrimento conta, conta aqui também; a causa não muda a dor.', 'O que se pode fazer agora é pouco e cauteloso; o reconhecimento muda prioridades e pesquisa.'], pensar='Antes desta lição, você imaginava a vida selvagem como boa? O que mudou? Que cautela você pediria antes de qualquer intervenção?'),
'animais-e-a-politica': dict(guardar=['Quem sofre e não vota é um problema político; representação sem voto já existe para crianças e incapazes.', 'Zoopolis, democracia senciente e constitucionalismo da senciência são três desenhos institucionais.', 'Alguns países têm comissários e dispositivos constitucionais; o Brasil reconhece a senciência em leis estaduais.'], pensar='Se os animais tivessem um representante no Congresso, que votação recente sairia diferente? Que desenho institucional você acha mais viável no Brasil?'),
'gradualismo': dict(guardar=['Duas perguntas que se confundem: o peso de uma dor igual e o que a morte tira.', 'Capacidades não mudam o peso de uma dor igual (senão graduariam humanos); mudam o que se perde com a morte.', 'A intensidade da experiência não acompanha a inteligência.'], pensar='Você acha que a dor de um frango vale menos que a sua? Com a distinção da lição, o que você mantém e o que revisa?'),
'geracoes-futuras': dict(guardar=['A distância no tempo não muda a dor de quem a sente; descontar vidas futuras é um temporalismo que poucos defendem ao dizer alto.', 'Desconta-se dinheiro e incerteza, não o valor de uma vida.', 'O problema da não identidade pede uma ética impessoal para o futuro.'], pensar='Que decisão sua desta semana terá efeito daqui a cinquenta anos? Você deu a esse efeito o mesmo peso que daria se fosse amanhã?'),
'mentes-artificiais': dict(guardar=['Carbonismo é uma delimitação do círculo: exclui por um traço (o substrato) cuja relevância não foi demonstrada.', 'Os indicadores de senciência em animais vêm de parentesco e fisiologia, que a IA não tem; o comportamento verbal é o que ela imita.', 'A posição razoável é a dúvida: não atribuir sem evidência, não criar o que sofreria se a hipótese for verdadeira, investigar.'], pensar='Se uma IA dissesse que sofre, o que faria você acreditar ou não? Que evidência você exige dela que não exige de um cão?'),
'vida-e-ecossistemas': dict(guardar=['Biocentrismo: toda vida tem valor por si; ecocentrismo: ecossistemas contam acima dos indivíduos.', 'O último homem testa se a natureza tem valor sem ninguém para quem seja boa.', 'A crítica sencientista: um ecossistema não sente a diferença entre existir e não existir; seus habitantes sentem.'], pensar='Você condenaria o último homem por destruir uma floresta vazia? Se sim, contra quem foi o erro? Se não, o que torna a floresta valiosa quando há alguém nela?'),
'etica-climatica': dict(guardar=['O clima é o maior problema de ação coletiva: dano difuso, agentes dispersos, benefício futuro.', 'Histórico, capacidade e emissão per capita apontam para os países ricos; a disputa é sobre quanto.', 'A crítica humanista e sencientista: protegemos o clima por quem vive nele, humanos e animais, não por si.'], pensar='Quando você diz que quer “proteger o planeta”, quem você quer proteger? Se a resposta inclui os animais, sua posição é sencientista, não só ambientalista.'),
'etica-populacional': dict(guardar=['A conclusão repugnante segue da soma: um mundo enorme de vidas mal valendo a pena vence um mundo de vidas excelentes.', 'Cada saída (média, limiar, pessoas afetadas) paga com outra conclusão estranha.', 'A assimetria (não criar vidas ruins é dever; criar vidas boas não é) é a intuição mais firme e a mais difícil de encaixar.'], pensar='Você acha que criar uma pessoa feliz é um dever, uma permissão ou nada? E impedir que nasça uma pessoa que sofreria? A diferença entre as respostas é a assimetria.'),
'identidade-pessoal-e-etica': dict(guardar=['Parfit: o que importa é a continuidade psicológica, não a identidade; a pergunta “é você?” pode ser vazia.', 'Se o eu futuro é alguém ligado a mim por laços fracos, a prudência se parece com a moral e o egoísmo perde o chão.', 'Punição, promessas e diretivas antecipadas dependem de quanto a pessoa de agora é a de antes.'], pensar='Quanto você se sente a mesma pessoa de dez anos atrás? Se o seu eu de daqui a trinta anos é quase outro, por que cuidar dele mais do que de um estranho?'),
'incerteza-moral': dict(guardar=['Incerteza moral é não saber qual teoria está certa; é a condição normal, e há métodos para decidir sob ela.', 'Seguir a teoria favorita ignora a gravidade; a escolha esperada pesa gravidade por probabilidade; o parlamento moral evita o fanatismo.', 'Sobre quem conta, a cobertura de riscos favorece incluir: o custo de errar excluindo é maior.'], pensar='Dê uma probabilidade às três famílias de teorias para você. Diante de um ato que uma delas condena com gravidade, o que a sua distribuição manda fazer?'),
'teoria-da-decisao-e-etica': dict(guardar=['Valor esperado é probabilidade vezes valor, e é o guia quando as apostas se repetem; dominância é o critério mais seguro.', 'Aversão ao risco e maximin são respostas razoáveis em apostas únicas e graves.', 'O fanatismo (uma chance minúscula de um ganho astronômico dominando tudo) é o problema do valor esperado nos extremos.'], pensar='Você escolheria salvar 100 com certeza ou ter 10% de salvar 2.000? E 1% de 20.000? Em que ponto sua resposta muda, e que atitude diante do risco ela revela?'),
'probabilidade-e-etica': dict(guardar=['Pense em graus de crença e atualize-os com a evidência (Bayes).', 'Probabilidade de senciência vezes número de seres pode ser enorme mesmo com probabilidade baixa.', 'Calibração se mede e se treina: das coisas a que você dá 70%, cerca de 70% devem ser verdadeiras.'], pensar='Que probabilidade você dá a estar errado sobre a sua posição moral mais firme? Se não é zero, o que essa margem deveria mudar na forma como você age?'),
'pluralismo-de-valores': dict(guardar=['Valores genuínos conflitam e não se reduzem a uma moeda comum (Berlin); incomensurável não é incomparável.', 'Dilemas trágicos deixam resíduo moral: o pesar depois da escolha certa é adequado.', 'Pluralismo não é relativismo: os valores em conflito são objetivos, e por isso o conflito dói.'], pensar='Lembre de uma escolha em que, mesmo acertando, algo valioso se perdeu. Você sentiu o resíduo? Hoje você acha que ele foi irracional, ou a reação certa?'),
'riscos-s-e-riscos-x': dict(guardar=['Riscos X ameaçam a existência da humanidade; riscos S ameaçam criar sofrimento em escala astronômica, e podem ser piores.', 'As agendas convergem em evitar catástrofes irreversíveis deste século e manter a capacidade de corrigir erros.', 'Divergem em prioridade quando é preciso escolher entre existir e existir bem.'], pensar='Entre um futuro em que a humanidade acaba sem dor e outro em que sobrevive mantendo trilhões em sofrimento, qual é pior para você? Sua resposta diz que risco você prioriza.'),
'quanto-a-moral-pode-exigir': dict(guardar=['Se cada quantia pode salvar uma vida, o argumento de Singer parece exigir quase tudo; a objeção da exigência responde que há um teto.', 'As saídas: consequencialismo satisfatório, regras, prerrogativas do agente, santos morais.', 'A posição prática mais defendida é um compromisso regular e significativo que se sustenta por anos.'], pensar='Qual é a sua resposta ao argumento: rejeita uma premissa, aceita prerrogativas, ou aceita a conclusão e não vive de acordo? Qual das três é mais honesta no seu caso?'),
'da-etica-a-politica': dict(guardar=['Primeiro a ética (quem conta, o que vale), depois a política (o arranjo que realiza isso).', 'Toda política carrega respostas éticas escondidas, inclusive sobre quem não vota nem fala.', 'Ética não é partido: quem parte da ética muda de lado conforme o tema.'], pensar='Pegue uma política que você apoia. Quem ela conta e quem ela esquece? Sua resposta mudaria se você partisse da ética e não do partido?'),
'progresso-moral': dict(guardar=['Progresso se distingue de moda por coerência, inclusão e evidência.', 'A principal forma de progresso é incluir quem ficava fora do círculo.', 'Nada é garantido: houve retrocessos longos, e o progresso acontece onde pessoas o fazem.'], pensar='Qual avanço moral dos últimos cem anos você acha mais frágil hoje? O que o sustentaria, e o que você pode fazer por isso?'),
'catastrofes-morais': dict(guardar=['Catástrofes reconhecidas são as que já não conseguimos negar; as em curso são as que ainda negamos.', 'Williams: toda sociedade cometeu um mal grave achando normal; seria estranho que a nossa fosse a exceção.', 'Baumann: as piores catástrofes podem ser futuras, em escala astronômica; reduzir a chance delas é prioridade.'], pensar='Se o nosso tempo tem uma catástrofe moral em curso, qual é a sua melhor aposta? O que faz você hesitar em agir sobre ela: dúvida, custo ou normalidade?'),
'abertura-moral': dict(guardar=['Diante de um argumento forte, há três perfis: fechar, ceder, revisar; o terceiro é raro e desejável.', 'Revisar bem é dar peso ao argumento que não se respondeu e mudar com tempo, por razão.', 'Abertura não é relativismo, e firmeza diante de argumentos ruins é parte da mesma virtude.'], pensar='Qual foi a última vez em que você mudou de ideia sobre algo moral? O que o convenceu? Se não lembra de nenhuma, o que isso diz?'),
}
